const body = $json.body || $json;

const content = String(body.content || body.text || "").trim();
const channelId = body.channel_id || body.channelId || "";

let command = "";
let game = "";
let route = "unknown";

const parts = content.split(/\s+/);
const first = (parts[0] || "").toLowerCase();

if (first.startsWith("!")) {
  command = first.slice(1);
  game = parts.slice(1).join(" ").trim();

  if (command === "price" || command === "game" || command === "history") {
    route = "lookup";
  } else if (command === "deals") {
    route = "deals";
  } else if (command === "freegames") {
    route = "deals";
  } else if (command === "help") {
    route = "unknown";
  }
}

return {
  content,
  channel_id: channelId,
  command,
  game_name: game,
  route
};

let results = [];
try { results = JSON.parse($json.data); } catch (e) { results = []; }
if (!Array.isArray(results)) results = [];
const cmd = $('Parse Discord Command').item.json;
const wanted = (cmd.game_name || "").toLowerCase();
let best = results.find((r) => (r.title || "").toLowerCase() === wanted) || results[0] || null;
return {
  channel_id: cmd.channel_id,
  command: cmd.command,
  game_name: cmd.game_name,
  matched_id: best ? best.id : "",
  matched_title: best ? best.title : cmd.game_name,
  found: !!best,
};

const match = $('Extract Best Game Match').item.json;

const priceNode = $('Fetch ITAD Game Prices').item.json;
const historyNode = $('Load Stored Price History').item.json || {};

// Parse ITAD price response
let prices = [];

try {
  if (typeof priceNode.data === "string") {
    prices = JSON.parse(priceNode.data);
  } else if (Array.isArray(priceNode.data)) {
    prices = priceNode.data;
  }
} catch (e) {
  prices = [];
}

const game = prices[0];

let reply = `🎮 ${match.matched_title}\n\n`;

if (!game || !game.deals || game.deals.length === 0) {
  reply += `No current store prices available.\n\n`;
} else {
  reply += `💰 Current Prices\n`;

  for (const deal of game.deals) {
    const shop = deal.shop?.name || "Unknown Store";
    const amount = deal.price?.amount;
    const currency = deal.price?.currency || "INR";

    if (amount != null) {
      reply += `🏪 ${shop}: ${currency} ${amount}\n`;
    }
  }

  reply += `\n`;
}

// Historical low
const historicalLow = game?.historyLow?.all;

if (historicalLow?.amount != null) {
  reply += `📊 Historical Low\n`;
  reply += `${historicalLow.currency} ${historicalLow.amount}\n`;
} else if (historyNode && Object.keys(historyNode).length > 0) {
  reply += `📊 Price History\n`;
  reply += `Stored history is available.\n`;
} else {
  reply += `📊 Price History\n`;
  reply += `Historical price information is unavailable.\n`;
}

return {
  channel_id: match.channel_id,
  reply
};

const channel_id = $('Parse Discord Command').first().json.channel_id;
let payload = {};
try { payload = JSON.parse($json.data || "{}"); } catch (e) { payload = {}; }
const list = (payload && payload.list) || [];
const fmt = (n) => "\u20b9" + Number(n || 0).toLocaleString("en-IN");
const freeOnly = $('Parse Discord Command').first().json.command === "freegames";
let deals = list;
if (freeOnly) deals = list.filter((d) => d.deal && (Number(d.deal.price.amount) === 0 || Number(d.deal.cut) === 100));
let lines = [freeOnly ? "\ud83c\udd93 FREE GAMES" : "\ud83d\udd25 TOP CURRENT DEALS", ""];
if (deals.length === 0) {
  lines.push(freeOnly ? "No free games found right now." : "No deals found right now.");
} else {
  let i = 1;
  for (const d of deals.slice(0, 10)) {
    const title = d.title || (d.game && d.game.title) || "Unknown";
    const deal = d.deal || {};
    const cur = deal.price ? Number(deal.price.amount) : 0;
    const cut = deal.cut != null ? deal.cut : 0;
    const shop = deal.shop ? deal.shop.name : "";
    const url = deal.url || "";
    lines.push(i + ". " + title + " - " + fmt(cur) + " (" + cut + "% off) @ " + shop);
    if (url) lines.push("   \ud83d\udd17 " + url);
    i++;
  }
}
return [{ json: { channel_id, reply: lines.join("\n").slice(0, 1990) } }];

const channel_id = $('Parse Discord Command').first().json.channel_id;
const reply = [
  "\ud83e\udd16 Game Price Bot - Commands",
  "",
  "!price <game>  - current prices + history",
  "!game <game>   - same as !price",
  "!history <game> - price history for a game",
  "!deals          - top current deals",
  "!freegames      - currently free games",
].join("\n");
return [{ json: { channel_id, reply } }];
